-- ROLLBACK for supabase/data_fixes/2026-10-06_review_link_fixes.sql
-- ---------------------------------------------------------------------
-- Restores every review link/rating and every fountain's city, source,
-- neighbourhood and description to the values in the backup taken
-- 2026-10-20 (backups/2026-10-20/), removes the fountains, cities and
-- sources the fix added, and puts back the original updated_at times.
-- Generated from the backup files; tested on a local copy, where the
-- table fingerprints (supabase/tests/checksums.sql) came back identical
-- to the pre-fix database.
-- =====================================================================
begin;

-- the updated_at triggers would stamp "now" on every restored row
alter table public.reviews   disable trigger reviews_touch_updated_at;
alter table public.fountains disable trigger fountains_touch_updated_at;

